const input = $input.first()?.json ?? {};
const source = input.query ?? input;
const intValue = (value) => {
  if (value === null || value === undefined || value === '') return null;
  const parsed = Number.parseInt(String(value), 10);
  return Number.isInteger(parsed) ? parsed : null;
};
return [{
  json: {
    batch_id: intValue(source.batch_id ?? source.batchId),
    member_id: intValue(source.member_id ?? source.raw_member_id),
    member: source.member ?? '',
    membership: source.membership ?? '',
    email_address: source.email_address ?? source.email ?? '',
    target_membership: source.target_membership ?? source.targetMembership ?? '',
    notes: source.notes ?? '',
    created_by: source.created_by ?? source.request_source ?? 'clubspark_package_import_queue_workflow'
  }
}];

const result = $input.first()?.json ?? {};
const escapeHtml = (value) => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/\"/g, '&quot;')
  .replace(/'/g, '&#39;');
const responseCode = Number(result.response_code ?? (result.ok === false ? 400 : 200));
const isSuccess = responseCode >= 200 && responseCode < 300;
const details = [
  ['Batch', result.batch_id],
  ['Member', result.member],
  ['Target package', result.target_membership],
  ['Status', result.status],
].filter(([, value]) => value !== null && value !== undefined && String(value).trim() !== '');
const detailHtml = details.map(([label, value]) => `<div class="detail"><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong></div>`).join('');
const html = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>ClubSpark Package Import Queue Result</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f4f7fb;
      --panel: #ffffff;
      --ink: #1f2937;
      --muted: #667085;
      --line: #d7e0ea;
      --success: #166534;
      --success-soft: #ecfdf3;
      --error: #b42318;
      --error-soft: #fef3f2;
      --button: #e9eef5;
    }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      padding: 24px;
      background: linear-gradient(180deg, #fbfdff 0%, var(--bg) 100%);
      color: var(--ink);
      font-family: Lato, Arial, sans-serif;
    }
    .panel {
      max-width: 760px;
      margin: 0 auto;
      background: var(--panel);
      border: 1px solid var(--line);
      border-radius: 18px;
      padding: 28px;
      box-shadow: 0 20px 40px rgba(15, 23, 42, 0.08);
    }
    .badge {
      display: inline-flex;
      padding: 6px 12px;
      border-radius: 999px;
      font-size: 13px;
      font-weight: 700;
      letter-spacing: 0.04em;
      text-transform: uppercase;
      color: ${isSuccess ? 'var(--success)' : 'var(--error)'};
      background: ${isSuccess ? 'var(--success-soft)' : 'var(--error-soft)'};
    }
    h1 {
      margin: 16px 0 8px;
      font-size: 32px;
      line-height: 1.1;
    }
    p {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
      font-size: 16px;
    }
    .details {
      display: grid;
      gap: 12px;
      grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
      margin-top: 24px;
    }
    .detail {
      border: 1px solid var(--line);
      border-radius: 14px;
      padding: 14px 16px;
      background: #f8fafc;
    }
    .detail span {
      display: block;
      margin-bottom: 6px;
      color: var(--muted);
      font-size: 13px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.04em;
    }
    .detail strong {
      font-size: 17px;
      line-height: 1.4;
      word-break: break-word;
    }
    .actions {
      display: flex;
      gap: 12px;
      flex-wrap: wrap;
      margin-top: 24px;
    }
    button {
      appearance: none;
      border: 1px solid var(--line);
      border-radius: 999px;
      background: var(--button);
      color: var(--ink);
      font: inherit;
      font-weight: 700;
      padding: 12px 18px;
      cursor: pointer;
    }
  </style>
</head>
<body>
  <main class="panel">
    <span class="badge">${isSuccess ? 'Success' : 'Action needed'}</span>
    <h1>ClubSpark package import queue</h1>
    <p>${escapeHtml(result.message ?? (isSuccess ? 'Package import item queued.' : 'The request could not be completed.'))}</p>
    ${detailHtml ? `<section class="details">${detailHtml}</section>` : ''}
    <div class="actions">
      <button type="button" onclick="window.close()">Close</button>
    </div>
  </main>
</body>
</html>`;
return [{ json: { ...result, response_code: responseCode, html } }];
